export const title = "Will an Add-On Headrest Fit Your Office Chair?";
export const metaTitle = "Will an Add-On Headrest Fit Your Office Chair?";
export const metaDescription = "Confirm compatibility with the exact chair model and generation, inspect the approved mounting point, and compare the headrest's adjustment range with.";
export const author = "Jamie Cole, Lead Product Researcher";
